class Solution {
public:
    vector<string> findRelativeRanks(vector<int>& score) {
        int n = score.size();
        vector<pair<int, int>> pairs(n);
        for (int i = 0; i < n; i++) pairs[i] = {score[i], i};
        sort(pairs.rbegin(), pairs.rend());
        vector<string> res(n);
        for (int rank = 0; rank < n; rank++) {
            int idx = pairs[rank].second;
            if (rank == 0) res[idx] = "Gold Medal";
            else if (rank == 1) res[idx] = "Silver Medal";
            else if (rank == 2) res[idx] = "Bronze Medal";
            else res[idx] = to_string(rank + 1);
        }
        return res;
    }
};

class Solution {
    public String[] findRelativeRanks(int[] score) {
        int n = score.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;
        Arrays.sort(indices, (a, b) -> Integer.compare(score[b], score[a]));
        String[] res = new String[n];
        for (int rank = 0; rank < n; rank++) {
            int idx = indices[rank];
            if (rank == 0) res[idx] = "Gold Medal";
            else if (rank == 1) res[idx] = "Silver Medal";
            else if (rank == 2) res[idx] = "Bronze Medal";
            else res[idx] = String.valueOf(rank + 1);
        }
        return res;
    }
}

var findRelativeRanks = function(score) {
    const n = score.length;
    const pairs = score.map((s, i) => [s, i]);
    pairs.sort((a, b) => b[0] - a[0]);
    const res = new Array(n);
    for (let rank = 0; rank < n; rank++) {
        const idx = pairs[rank][1];
        if (rank === 0) res[idx] = "Gold Medal";
        else if (rank === 1) res[idx] = "Silver Medal";
        else if (rank === 2) res[idx] = "Bronze Medal";
        else res[idx] = String(rank + 1);
    }
    return res;
};
